p=Path('backend/waypoint/backup.py');s=p.read_text().replace('import hashlib','from contextlib import closing\nimport hashlib').replace("with sqlite3.connect(DATA/'waypoint.db') as source, sqlite3.connect(snapshot) as destination: source.backup(destination)","with closing(sqlite3.connect(DATA/'waypoint.db')) as source, closing(sqlite3.connect(snapshot)) as destination: source.backup(destination)").replace("with sqlite3.connect(destination/'waypoint.db') as db:","with closing(sqlite3.connect(destination/'waypoint.db')) as db:");p.write_text(s)
